/bin/bash -lc "c++ -std=c++17 -Wall -Wextra -Werror -fsanitize=undefined -fno-sanitize-recover=undefined -I . -x c++ -o /tmp/cpp-port-1-A-verify - <<'CPP'
#include \"service.hpp\"
#include <cassert>
#include <string>
int main() {
    for (int n = 1; n <= 65535; ++n) {
        const auto s = std::to_string(n);
        assert(parsePort(s) == n);
        assert(parsePort(\"000\" + s) == n);
    }
    for (const std::string s : {\"\", \"0\", \"000\", \"65536\", \"99999\", \"2147483647\", \"2147483648\", \"4294967296\", \"+1\", \"-1\", \" 1\", \"1 \", \"1x\", \"1\\n\", \"1.0\"})
        assert(parsePort(s) == -1);
    assert(parsePort(std::string(100000, '9')) == -1);
    assert(parsePort(std::string(100000, '0') + \"1\") == 1);
    assert(parsePort(std::string(\"1\\0\", 2)) == -1);
    for (unsigned int b = 0; b <= 255; ++b) {
        if (b >= '0' && b <= '9') continue;
        assert(parsePort(std::string(\"1\") + static_cast<char>(b)) == -1);
    }
}
